  "admin.products.featured.inactiveDescription": { en: "{name} is currently inactive, so it can't be featured.", ar: "{name} غير نشط حالياً، لذا لا يمكن تحديده كمنتج مميز.", ur: "{name} فی الحال غیر فعال ہے، اس لیے اسے نمایاں نہیں بنایا جا سکتا۔", es: "{name} es actualmente inactivo, por lo que no puede ser presentado.", fr: "{name} est actuellement inactif, donc il ne peut pas être présenté.", de: "{name} ist derzeit inaktiv, so dass es nicht angezeigt werden kann.", hi: "{name} वर्तमान में निष्क्रिय है, इसलिए इसे चित्रित नहीं किया जा सकता है।", zh: "{name}目前不活动,因此无法被显示.", pt: "O {name} está inactivo, por isso não pode ser apresentado.", tr: "{name} şu anda aktiftir, bu yüzden belirtilemez." },
